def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    ordered = sorted(lst)
    gaps = [ordered[i + 1] - ordered[i] for i in range(len(ordered) - 1)]
    return max(gaps)

def leetspeak(s):
    mapping = {'a': '4', 'e': '3', 'i': '1', 'o': '0', 's': '5', 't': '7'}
    result = []
    for ch in s:
        lower_ch = ch.lower()
        if lower_ch in mapping:
            result.append(mapping[lower_ch])
        else:
            result.append(ch)
    return ''.join(result)

