def sentence_case_preserve_acronyms(s, acronyms):
    lowered = s.lower()
    chars = list(lowered)
    for i, ch in enumerate(chars):
        if ch.isalpha():
            chars[i] = ch.upper()
            break
    sentence = ''.join(chars)
    acronym_lookup = {a.lower(): a for a in acronyms}
    words = sentence.split(' ')
    fixed = [acronym_lookup[w.lower()] if w.lower() in acronym_lookup else w for w in words]
    return ' '.join(fixed)

