def is_valid_luhn_number(s):
    if len(s) < 2 or not s.isdigit():
        return False
    digits = [int(c) for c in s][::-1]
    total = 0
    for i, d in enumerate(digits):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

