def oxford_join_quoted(items):
    parts = []
    for it in items:
        parts.append('"' + str(it) + '"')
    if not parts:
        return ''
    if len(parts) == 1:
        return parts[0]
    if len(parts) == 2:
        return parts[0] + ' and ' + parts[1]
    head = ', '.join(parts[:-1])
    return head + ', and ' + parts[-1]
